$ok=['jpg'=>'image','jpeg'=>'image','png'=>'image','webp'=>'image','mp4'=>'video','mov'=>'video','m4v'=>'video','webm'=>'video'];$msg='';$K=['Driver','Co-driver','Team owner','Mechanic','Marshal','Fan'];
