 if($a=='post'&&trim($_POST['title'])){$db->prepare('INSERT INTO posts(title,body) VALUES(?,?)')->execute([trim($_POST['title']),trim($_POST['body'])]);$msg='News published.';if(!empty($_POST['notify'])){require_once 'push.php';[$sn]=push_all(trim($_POST['title']),mb_strimwidth(trim($_POST['body']),0,120,'...'),'/#news');$msg.=' Notification sent to '.$sn.' device'.($sn==1?'':'s').'.';}}
 if($a=='media'){$f=$_FILES['f']??null;$er=$f['error']??4;$e=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));
  if($er!==0)$msg=[1=>'File is bigger than the server limit.',2=>'File is bigger than the server limit.',3=>'Upload was interrupted. Try again.',4=>'No file was chosen.'][$er]??'Upload failed.';
  elseif(!isset($ok[$e]))$msg='Cannot use .'.$e.' files. Use mp4, mov, m4v, webm, jpg, png or webp.';
  elseif(!is_dir(__DIR__.'/uploads/files')||!move_uploaded_file($f['tmp_name'],__DIR__.'/'.($p='uploads/files/'.bin2hex(random_bytes(8)).".$e")))$msg='The server could not save the file (storage may be full).';
  else{$db->prepare('INSERT INTO media(kind,path,caption,sort) VALUES(?,?,?,(SELECT COALESCE(MAX(sort),0)+1 FROM media))')->execute([$ok[$e],$p,trim($_POST['cap']??'')]);$msg='Uploaded.';$good=1;}
  if($ajax)jout(!empty($good),$msg);}
 if($a=='banner'){$db->prepare("REPLACE INTO settings(k,v) VALUES('banner',?)")->execute([trim($_POST['b'])]);$msg='Banner saved.';}
 if($a=='event'&&trim($_POST['title'])){$db->prepare('INSERT INTO events(title,day,place) VALUES(?,?,?)')->execute([trim($_POST['title']),$_POST['day'],trim($_POST['place'])]);$msg='Event added.';}
 if($a=='delevent')$db->prepare('DELETE FROM events WHERE id=?')->execute([$_POST['id']]);
 if($a=='edituser'){try{$p=[trim($_POST['name']),strtolower(trim($_POST['email'])),in_array($_POST['kind'],$K)?$_POST['kind']:'Fan',$_POST['age']=='Junior'?'Junior':'Senior',trim($_POST['team']??''),trim($_POST['car_type']??''),trim($_POST['inspired']??''),trim($_POST['phone'])];$q='UPDATE users SET name=?,email=?,kind=?,age_group=?,team=?,car_type=?,inspired=?,phone=? ';if(strlen($_POST['pass'])>=8){$q.=',pass=? ';$p[]=password_hash($_POST['pass'],PASSWORD_DEFAULT);}$p[]=$_POST['id'];$db->prepare($q."WHERE id=? AND role!='admin'")->execute($p);$msg='Member updated.';}catch(Exception $x){$msg='That email is already used.';}}
 if($a=='editmedia'){$db->prepare('UPDATE media SET caption=? WHERE id=?')->execute([trim($_POST['cap']),$_POST['id']]);$msg='Caption saved.';}
 if($a=='restore'||$a=='restoreall'){$have=$db->query('SELECT path FROM media')->fetchAll(PDO::FETCH_COLUMN);foreach(glob(__DIR__.'/uploads/seed/*.{jpg,jpeg,png,webp}',GLOB_BRACE) as $f){$b=basename($f);if(($a=='restoreall'||$b==($_POST['f']??''))&&!in_array("uploads/seed/$b",$have)){$db->prepare("INSERT INTO media(kind,path,caption,sort) VALUES('image',?,?,(SELECT COALESCE(MAX(sort),0)+1 FROM media))")->execute(["uploads/seed/$b",$cap[(int)substr($b,1)-1]??'']);}}$msg='Photos restored.';}
 if($a=='adminpw'&&strlen($_POST['pass'])>=8){$db->prepare("UPDATE users SET pass=? WHERE role='admin'")->execute([password_hash($_POST['pass'],PASSWORD_DEFAULT)]);$msg='Admin password changed.';}
 if($a=='setcover'){$db->prepare("REPLACE INTO settings(k,v) VALUES('hero_media',?)")->execute([(int)$_POST['id']]);$msg='Cover video set. It now plays on the home page.';}
 if($a=='cover'){foreach(['hero_title'=>'ht','hero_sub'=>'hs','hero_btn'=>'hb'] as $k=>$f)$db->prepare('REPLACE INTO settings(k,v) VALUES(?,?)')->execute([$k,trim($_POST[$f]??'')]);$mid=(int)($_POST['hm']??0);if($mid)$db->prepare('REPLACE INTO settings(k,v) VALUES(?,?)')->execute(['hero_media',$mid]);else $db->exec("DELETE FROM settings WHERE k='hero_media'");$msg='Cover saved.';}
 if($a=='clearcover'){$db->prepare("DELETE FROM settings WHERE k='hero_media'")->execute();$msg='The cover is the photo again.';}
 if($a=='reorder'){$ids=array_filter(array_map('intval',explode(',',$_POST['ids']??'')));$st=$db->prepare('UPDATE media SET sort=? WHERE id=?');$n=0;foreach($ids as $i)$st->execute([++$n,$i]);if($ajax)jout(true,'Order saved.');$msg='Order saved.';}
 if($a=='togglefeat'){$db->prepare('UPDATE media SET featured=CASE WHEN COALESCE(featured,0)=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);$msg='Home page selection updated.';}
 if($a=='addsponsor'){$f=$_FILES['logo']??null;$im=($f&&$f['error']===0&&$f['size']<=5*1048576)?@getimagesize($f['tmp_name']):false;$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$im['mime']??'']??'';$nm=trim($_POST['name']??'');
  if(!$ext||!$nm)$msg='Please enter a name and choose a JPG, PNG or WebP logo under 5 MB.';
  else{$p='uploads/files/sp'.bin2hex(random_bytes(6)).'.'.$ext;if(is_dir(__DIR__.'/uploads/files')&&move_uploaded_file($f['tmp_name'],__DIR__.'/'.$p)){$u=trim($_POST['url']??'');$db->prepare('INSERT INTO sponsors(name,logo,url,sort) VALUES(?,?,?,(SELECT COALESCE(MAX(sort),0)+1 FROM sponsors))')->execute([$nm,$p,preg_match('#^https?://#i',$u)?$u:'']);$msg='Sponsor added.';}else $msg='The server could not save the logo.';}}
 if($a=='editsponsor'){$u=trim($_POST['url']??'');$db->prepare('UPDATE sponsors SET name=?,url=? WHERE id=?')->execute([trim($_POST['name']??''),preg_match('#^https?://#i',$u)?$u:'',(int)($_POST['id']??0)]);$msg='Sponsor saved.';}
 if($a=='delsponsor'){$s=$db->prepare('SELECT logo FROM sponsors WHERE id=?');$s->execute([(int)($_POST['id']??0)]);$lg=$s->fetchColumn();if($lg&&strpos($lg,'uploads/files/sp')===0)@unlink(__DIR__.'/'.$lg);$db->prepare('DELETE FROM sponsors WHERE id=?')->execute([(int)($_POST['id']??0)]);$msg='Sponsors updated.';}
 if($a=='movesponsor'){$ids=array_map('intval',$db->query('SELECT id FROM sponsors ORDER BY sort,id')->fetchAll(PDO::FETCH_COLUMN));$i=array_search((int)($_POST['id']??0),$ids,true);$j=($i===false)?-1:$i+((int)($_POST['d']??0)<0?-1:1);if($i!==false&&isset($ids[$j])){[$ids[$i],$ids[$j]]=[$ids[$j],$ids[$i]];$st=$db->prepare('UPDATE sponsors SET sort=? WHERE id=?');foreach($ids as $k=>$x)$st->execute([$k+1,$x]);}$msg='Sponsors updated.';}
 if($a=='delpost')$db->prepare('DELETE FROM posts WHERE id=?')->execute([$_POST['id']]);
