<h3>Backups</h3><p><a class="btn" href="admin.php?backup=1">Download database backup</a> <a class="btn alt" href="admin.php?members=1">Download members list (CSV)</a></p><h3>Admin account</h3><form method="post"><input type="hidden" name="t" value="<?=$T?>"><input type="hidden" name="a" value="adminpw"><label>New admin password (8+ characters)<input type="password" name="pass" minlength="8" required></label><button class="btn">Change password</button></form><script>(function(){const K='rxdraft:',p=sessionStorage.getItem('rxp'),ok=/saved|published|added|updated|uploaded|changed|restored|confirmed|set\./i.test((document.querySelector('.err')||{}).textContent||'');
if(ok||!p){Object.keys(localStorage).filter(k=>k.startsWith(K)).forEach(k=>localStorage.removeItem(k));sessionStorage.removeItem('rxp')}
const fs=[...document.querySelectorAll('main form')];fs.forEach((f,i)=>{f.querySelectorAll('input:not([type=hidden]):not([type=file]):not([type=password]),textarea').forEach(el=>{if(!el.name)return;const k=K+i+':'+el.name,v=localStorage.getItem(k);if(v!==null&&v!=='')el.value=v;el.addEventListener('input',()=>localStorage.setItem(k,el.value))});f.addEventListener('submit',()=>sessionStorage.setItem('rxp','1'))})})()</script>
<script>(function(){const y=sessionStorage.getItem('rxy');if(y!==null){sessionStorage.removeItem('rxy');scrollTo(0,+y)}
document.addEventListener('submit',e=>{if(!e.defaultPrevented)sessionStorage.setItem('rxy',scrollY)});
const g=document.getElementById('mg');if(!g)return;let dr=null;const T=document.querySelector('input[name=t]').value;
function save(){const d=new FormData();d.append('t',T);d.append('a','reorder');d.append('ids',[...g.children].map(c=>c.dataset.id).join(','));const x=new XMLHttpRequest();x.open('POST','admin.php');x.setRequestHeader('X-Requested-With','fetch');x.send(d)}
g.addEventListener('dragstart',e=>{dr=e.target.closest('.mem');if(dr)dr.style.opacity='.4'});g.addEventListener('dragend',()=>{if(dr)dr.style.opacity='';dr=null});
g.addEventListener('dragover',e=>{e.preventDefault();const t=e.target.closest('.mem');if(!dr||!t||t===dr)return;const r=t.getBoundingClientRect();g.insertBefore(dr,(e.clientX-r.left)>r.width/2?t.nextSibling:t)});
g.addEventListener('drop',e=>{e.preventDefault();save()});
g.addEventListener('click',e=>{const b=e.target.closest('[data-mv]');if(!b)return;const c=b.closest('.mem'),d=+b.dataset.mv;if(d<0&&c.previousElementSibling)g.insertBefore(c,c.previousElementSibling);if(d>0&&c.nextElementSibling)g.insertBefore(c.nextElementSibling,c);save();c.scrollIntoView({block:'nearest'})})})()</script>
